ALTER TABLE public.society_settings ADD COLUMN effective_month date NOT NULL DEFAULT (date_trunc('month',now())+interval '1 month')::date, ADD COLUMN due_day integer NOT NULL DEFAULT 1, ADD COLUMN fy_start_month integer NOT NULL DEFAULT 4, ADD COLUMN reminders_enabled boolean NOT NULL DEFAULT true, ADD COLUMN reminder_start_day integer NOT NULL DEFAULT 4, ADD COLUMN reminder_time time NOT NULL DEFAULT '10:00', ADD COLUMN reminder_timezone text NOT NULL DEFAULT 'Asia/Kolkata', ADD COLUMN reminder_frequency text NOT NULL DEFAULT 'daily', ADD COLUMN reminder_method text NOT NULL DEFAULT 'gmail', ADD COLUMN payment_notifications boolean NOT NULL DEFAULT true;
CREATE TABLE public.maintenance_rates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),effective_month date NOT NULL UNIQUE,monthly_amount numeric NOT NULL,due_day integer NOT NULL,fy_start_month integer NOT NULL,approved_by uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.maintenance_rates TO authenticated; GRANT ALL ON public.maintenance_rates TO service_role; ALTER TABLE public.maintenance_rates ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Signed in read approved maintenance rates" ON public.maintenance_rates FOR SELECT TO authenticated USING(true);
CREATE TABLE public.maintenance_bills (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),flat_id uuid NOT NULL REFERENCES public.flats(id) ON DELETE CASCADE,bill_month date NOT NULL,amount numeric NOT NULL,due_date date NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(flat_id,bill_month));
GRANT SELECT ON public.maintenance_bills TO authenticated; GRANT ALL ON public.maintenance_bills TO service_role; ALTER TABLE public.maintenance_bills ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read permitted maintenance bills" ON public.maintenance_bills FOR SELECT TO authenticated USING(public.has_permission('finance.read') OR EXISTS(SELECT 1 FROM public.flats f WHERE f.id=flat_id AND f.resident_user_id=auth.uid()));
CREATE TABLE public.reminder_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),run_date date NOT NULL UNIQUE,started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,status text NOT NULL DEFAULT 'queued',recorded integer NOT NULL DEFAULT 0,sent integer NOT NULL DEFAULT 0,failed integer NOT NULL DEFAULT 0,error text);
GRANT SELECT ON public.reminder_runs TO authenticated; GRANT ALL ON public.reminder_runs TO service_role; ALTER TABLE public.reminder_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Committee read reminder execution" ON public.reminder_runs FOR SELECT TO authenticated USING(public.has_permission('admin.read'));
INSERT INTO public.maintenance_rates(effective_month,monthly_amount,due_day,fy_start_month) VALUES('1900-01-01',1500,1,4);
INSERT INTO public.maintenance_bills(flat_id,bill_month,amount,due_date) SELECT f.id,m::date,1500,m::date FROM public.flats f CROSS JOIN LATERAL generate_series(date_trunc('month',f.billing_start),date_trunc('month',now() AT TIME ZONE 'Asia/Kolkata'),interval '1 month') m;
CREATE FUNCTION public.maintenance_rate(_month date) RETURNS public.maintenance_rates LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT r FROM public.maintenance_rates r WHERE effective_month<=date_trunc('month',_month)::date ORDER BY effective_month DESC LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.maintenance_rate(date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.maintenance_rate(date) TO authenticated,service_role;
CREATE FUNCTION public.maintenance_due_date(_month date,_day integer) RETURNS date LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT date_trunc('month',_month)::date + (least(_day,extract(day from date_trunc('month',_month)+interval '1 month - 1 day')::int)-1) $$;
REVOKE ALL ON FUNCTION public.maintenance_due_date(date,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.maintenance_due_date(date,integer) TO authenticated,service_role;
CREATE FUNCTION public.bill_amount(_flat uuid,_month date) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT amount FROM public.maintenance_bills WHERE flat_id=_flat AND bill_month=date_trunc('month',_month)::date),(public.maintenance_rate(_month)).monthly_amount,1500) $$;
REVOKE ALL ON FUNCTION public.bill_amount(uuid,date) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.bill_amount(uuid,date) TO service_role;
CREATE FUNCTION public.billed_total(_flat uuid,_start date,_end date) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(sum(public.bill_amount(_flat,m::date)),0) FROM generate_series(date_trunc('month',_start),date_trunc('month',_end)-interval '1 month',interval '1 month') m WHERE auth.uid() IS NULL OR public.has_permission('finance.read') OR EXISTS(SELECT 1 FROM public.flats f WHERE f.id=_flat AND f.resident_user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.billed_total(uuid,date,date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.billed_total(uuid,date,date) TO authenticated,service_role;
CREATE FUNCTION public.freeze_monthly_bills() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO public.maintenance_bills(flat_id,bill_month,amount,due_date) SELECT f.id,m::date,(public.maintenance_rate(m::date)).monthly_amount,public.maintenance_due_date(m::date,(public.maintenance_rate(m::date)).due_day) FROM public.flats f CROSS JOIN LATERAL generate_series(date_trunc('month',f.billing_start),date_trunc('month',now() AT TIME ZONE 'Asia/Kolkata'),interval '1 month') m ON CONFLICT(flat_id,bill_month) DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.freeze_monthly_bills() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.freeze_monthly_bills() TO service_role;
CREATE FUNCTION public.validate_society_configuration() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE changed boolean; localmonth date:=date_trunc('month',now() AT TIME ZONE 'Asia/Kolkata')::date; BEGIN
IF NEW.monthly_amount IS NULL OR NEW.due_day IS NULL OR NEW.fy_start_month IS NULL OR NEW.reminder_start_day IS NULL OR NEW.reminders_enabled IS NULL OR NEW.payment_notifications IS NULL OR NEW.reminder_time IS NULL OR NEW.monthly_amount<=0 OR NEW.monthly_amount>100000000 OR NEW.monthly_amount<>round(NEW.monthly_amount,2) THEN RAISE EXCEPTION 'Enter a positive maintenance amount with at most two decimal places'; END IF;
IF NEW.due_day NOT BETWEEN 1 AND 31 OR NEW.reminder_start_day NOT BETWEEN 1 AND 31 OR NEW.fy_start_month NOT BETWEEN 1 AND 12 THEN RAISE EXCEPTION 'Invalid day or financial year month'; END IF;
IF NEW.reminder_frequency IS DISTINCT FROM 'daily' OR NEW.reminder_method IS DISTINCT FROM 'gmail' THEN RAISE EXCEPTION 'Only the existing daily Gmail reminders are supported'; END IF;
IF NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=NEW.reminder_timezone) THEN RAISE EXCEPTION 'Invalid time zone'; END IF;
changed:=TG_OP='INSERT' OR (NEW.monthly_amount,NEW.due_day,NEW.fy_start_month,NEW.effective_month) IS DISTINCT FROM (OLD.monthly_amount,OLD.due_day,OLD.fy_start_month,OLD.effective_month);
IF changed THEN IF NEW.effective_month<=localmonth OR NEW.effective_month<>date_trunc('month',NEW.effective_month)::date THEN RAISE EXCEPTION 'The effective month must be a future month'; END IF;
IF TG_OP='UPDATE' AND NEW.fy_start_month<>OLD.fy_start_month AND extract(month from NEW.effective_month)<>NEW.fy_start_month THEN RAISE EXCEPTION 'A financial year change must start in its new starting month'; END IF;
INSERT INTO public.maintenance_rates(effective_month,monthly_amount,due_day,fy_start_month,approved_by) VALUES(NEW.effective_month,NEW.monthly_amount,NEW.due_day,NEW.fy_start_month,auth.uid()); END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_configuration BEFORE INSERT OR UPDATE ON public.society_settings FOR EACH ROW EXECUTE FUNCTION public.validate_society_configuration();
CREATE FUNCTION public.deny_billing_edits() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL THEN RAISE EXCEPTION 'Issued billing history cannot be changed'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_bills BEFORE UPDATE OR DELETE ON public.maintenance_bills FOR EACH ROW EXECUTE FUNCTION public.deny_billing_edits(); CREATE TRIGGER immutable_rates BEFORE UPDATE OR DELETE ON public.maintenance_rates FOR EACH ROW EXECUTE FUNCTION public.deny_billing_edits();
CREATE OR REPLACE VIEW public.flat_accounts WITH (security_invoker=true) AS WITH billed AS (SELECT f.id,f.flat_number,f.resident_name,f.mobile,f.resident_user_id,f.billing_start,greatest((date_part('year',CURRENT_DATE)-date_part('year',f.billing_start))*12+(date_part('month',CURRENT_DATE)-date_part('month',f.billing_start))+1,0)::int months_billed,coalesce((SELECT sum(p.amount) FROM public.payments p WHERE p.flat_id=f.id AND p.status='confirmed'),0)::numeric total_paid FROM public.flats f), totals AS (SELECT b.*,public.billed_total(id,billing_start,(date_trunc('month',CURRENT_DATE)+interval '1 month')::date) charged,CASE WHEN months_billed>0 THEN (public.maintenance_rate(CURRENT_DATE)).monthly_amount ELSE 0 END current_amount FROM billed b) SELECT id,flat_number,resident_name,mobile,resident_user_id,billing_start,months_billed,total_paid,charged::numeric total_charged,greatest(charged-total_paid,0)::numeric outstanding,current_amount::numeric current_month_amount,greatest(charged-current_amount-total_paid,0)::numeric previous_outstanding,CASE WHEN charged<=total_paid THEN 'paid' WHEN mod(greatest(charged-total_paid,0),nullif(current_amount,0))<>0 THEN 'partial' ELSE 'outstanding' END status FROM totals;
CREATE OR REPLACE VIEW public.finance_accounts WITH (security_barrier=true) AS WITH billed AS (SELECT f.id,f.flat_number,f.resident_name,f.billing_start,public.billed_total(f.id,f.billing_start,(date_trunc('month',CURRENT_DATE)+interval '1 month')::date) charged,coalesce((SELECT sum(p.amount) FROM public.payments p WHERE p.flat_id=f.id AND p.status='confirmed'),0) paid FROM public.flats f WHERE public.has_permission('finance.read')) SELECT id,flat_number,resident_name,billing_start,greatest(charged-paid,0) outstanding,(public.maintenance_rate(CURRENT_DATE)).monthly_amount current_month_amount,CASE WHEN charged<=paid THEN 'paid' WHEN mod(greatest(charged-paid,0),(public.maintenance_rate(CURRENT_DATE)).monthly_amount)<>0 THEN 'partial' ELSE 'outstanding' END status FROM billed;
CREATE OR REPLACE FUNCTION public.approval_fields(_module text) RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE _module WHEN 'flats' THEN ARRAY['flat_number','resident_name','mobile','resident_user_id','billing_start','occupancy','tenant_name','tenant_phone','tenant_email','tenant_start','tenant_end'] WHEN 'payments' THEN ARRAY['flat_id','amount','method','status','paid_on','month_covered','reference','notes'] WHEN 'expenses' THEN ARRAY['expense_date','expense_month','category','description','amount','paid_by','method','notes'] WHEN 'announcements' THEN ARRAY['title','category','description','event_date','event_time','location','expires_on','published'] WHEN 'fund_years' THEN ARRAY['opening_balance'] WHEN 'society_settings' THEN ARRAY['society_name','monthly_amount','upi_id','payee_name','effective_month','due_day','fy_start_month','reminders_enabled','reminder_start_day','reminder_time','reminder_timezone','reminder_frequency','reminder_method','payment_notifications'] ELSE NULL END $$;
CREATE FUNCTION public.validate_settings_proposal() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.society_settings; v jsonb; BEGIN IF NEW.module<>'society_settings' THEN RETURN NEW; END IF; IF NEW.action<>'update' THEN RAISE EXCEPTION 'Settings support updates only'; END IF; v:=NEW.previous_values||NEW.proposed_values; s:=jsonb_populate_record(NULL::public.society_settings,v);
IF s.monthly_amount IS NULL OR s.monthly_amount<=0 OR s.monthly_amount>100000000 OR s.monthly_amount<>round(s.monthly_amount,2) OR s.due_day IS NULL OR s.due_day NOT BETWEEN 1 AND 31 OR s.reminder_start_day IS NULL OR s.reminder_start_day NOT BETWEEN 1 AND 31 OR s.fy_start_month IS NULL OR s.fy_start_month NOT BETWEEN 1 AND 12 THEN RAISE EXCEPTION 'Invalid maintenance amount, due day or financial year month'; END IF;
IF s.reminder_frequency IS DISTINCT FROM 'daily' OR s.reminder_method IS DISTINCT FROM 'gmail' OR s.reminders_enabled IS NULL OR s.payment_notifications IS NULL OR s.reminder_time IS NULL OR NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=s.reminder_timezone) THEN RAISE EXCEPTION 'Invalid reminder settings'; END IF;
IF NEW.proposed_values ?| ARRAY['monthly_amount','due_day','fy_start_month','effective_month'] THEN IF s.effective_month IS NULL OR s.effective_month<=date_trunc('month',now() AT TIME ZONE 'Asia/Kolkata')::date OR s.effective_month<>date_trunc('month',s.effective_month)::date THEN RAISE EXCEPTION 'Choose a future effective month'; END IF; IF s.fy_start_month<>(NEW.previous_values->>'fy_start_month')::int AND extract(month from s.effective_month)<>s.fy_start_month THEN RAISE EXCEPTION 'A financial year change must start in its new starting month'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_settings_proposal BEFORE INSERT ON public.change_proposals FOR EACH ROW EXECUTE FUNCTION public.validate_settings_proposal();
CREATE FUNCTION public.reminder_is_due(_at timestamptz) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT reminders_enabled AND extract(day from _at AT TIME ZONE reminder_timezone)>=reminder_start_day AND (_at AT TIME ZONE reminder_timezone)::time>=reminder_time FROM public.society_settings WHERE id=true $$;
REVOKE ALL ON FUNCTION public.reminder_is_due(timestamptz) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reminder_is_due(timestamptz) TO service_role;
CREATE OR REPLACE FUNCTION public.record_maintenance_reminders() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE today date; n integer; BEGIN IF NOT coalesce(public.reminder_is_due(now()),false) THEN RETURN 0; END IF; SELECT (now() AT TIME ZONE reminder_timezone)::date INTO today FROM public.society_settings WHERE id=true; INSERT INTO public.maintenance_reminders(flat_id,reminder_date,amount_due) SELECT id,today,outstanding FROM public.flat_accounts WHERE outstanding>0 ON CONFLICT(flat_id,reminder_date) DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
CREATE OR REPLACE FUNCTION public.record_and_email_reminders() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE today date; n integer; run uuid; BEGIN PERFORM public.freeze_monthly_bills(); IF NOT coalesce(public.reminder_is_due(now()),false) THEN RETURN 0; END IF; SELECT (now() AT TIME ZONE reminder_timezone)::date INTO today FROM public.society_settings WHERE id=true; INSERT INTO public.reminder_runs(run_date) VALUES(today) ON CONFLICT(run_date) DO NOTHING RETURNING id INTO run; IF run IS NULL THEN RETURN 0; END IF; n:=public.record_maintenance_reminders(); UPDATE public.reminder_runs SET recorded=n WHERE id=run; IF n=0 THEN UPDATE public.reminder_runs SET status='no_dues',finished_at=now() WHERE id=run; RETURN 0; END IF; PERFORM net.http_post(url:='https://project--0fd07ec0-305c-47b1-a041-c1113df57b56.lovable.app/api/public/hooks/reminder-emails',headers:=jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||(SELECT token FROM public.internal_tokens WHERE name='email_hook')),body:=jsonb_build_object('run_id',run,'scheduled_date',today)); RETURN n; END $$;
COMMENT ON TABLE public.reminder_runs IS 'queued means callback requested, not email sent; completion is recorded only by the authenticated Gmail hook.';
CREATE OR REPLACE FUNCTION public.notify_payment_confirmed() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='confirmed' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'confirmed') AND coalesce((SELECT payment_notifications FROM public.society_settings WHERE id=true),false) THEN PERFORM net.http_post(url:='https://project--0fd07ec0-305c-47b1-a041-c1113df57b56.lovable.app/api/public/hooks/payment-email',headers:=jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||(SELECT token FROM public.internal_tokens WHERE name='email_hook')),body:=jsonb_build_object('payment_id',NEW.id)); END IF; RETURN NEW; END $$;